 "content": "def transform(grid):
    """Connect sparse 2-markers by a median-aligned 3-colored orthogonal tree."""
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2]
    if not points:
        return out

    # Prefer an already shared row as the horizontal trunk. Otherwise use the
    # median marker column as a vertical trunk (the demonstrated tie-free case).
    row_counts = {}
    for r, _ in points:
        row_counts[r] = row_counts.get(r, 0) + 1
    repeated_rows = [r for r, count in row_counts.items() if count >= 2]
    if repeated_rows:
        trunk_row = min(repeated_rows, key=lambda r: (abs(r - sorted(r0 for r0, _ in points)[len(points)//2]), r))
        cols = [c for _, c in points]
        for c in range(min(cols), max(cols) + 1):
            if out[trunk_row][c] == 0:
                out[trunk_row][c] = 3
        for r, c in points:
            step = 1 if trunk_row > r else -1
            for rr in range(r + step, trunk_row, step):
                if out[rr][c] == 0:
                    out[rr][c] = 3
    else:
        cols = sorted(c for _, c in points)
        trunk_col = cols[len(cols) // 2]
        rows = [r for r, _ in points]
        for r in range(min(rows), max(rows) + 1):
            if out[r][trunk_col] == 0:
                out[r][trunk_col] = 3
        for r, c in points:
            step = 1 if trunk_col > c else -1
            for cc in range(c + step, trunk_col, step):
                if out[r][cc] == 0:
                    out[r][cc] = 3
    return out
